const path="/Users/anudeepbonagiri/dev/hackathons/dispatch-ledger/seed/fixtures/evidence/telematics/88.csv";
const body=await tools.Read({file_path:path});
if(typeof body!=="string")throw new Error("Expected CSV text");
const rows=body.trimEnd().split("\n");
const truck2=rows.map((text,i)=>({line:i+1,text})).filter(r=>r.text.startsWith("2,"));
text({source:"telematics/88.csv",truck2});
const rad=x=>x*Math.PI/180;
const near=rows.slice(1).map((text,i)=>{const c=text.split(",");const a=Math.sin(rad(Number(c[2])-28.4008)/2)**2+Math.cos(rad(28.4008))*Math.cos(rad(Number(c[2])))*Math.sin(rad(Number(c[3])+97.7486)/2)**2;return {line:i+2,text,at:c[1],within3000:6371000*2*Math.atan2(Math.sqrt(a),Math.sqrt(1-a))<=3000};}).filter(r=>r.within3000);
text({source:"telematics/88.csv",stationAreaPingsAllDay:near.map(({line,text})=>({line,text})),stationAreaPingsInRequestedWindow:near.filter(r=>r.at>="2026-10-30T15:07:45Z"&&r.at<="2026-10-30T15:27:45Z").map(({line,text})=>({line,text}))});
